const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{display:block;height:100%;overflow:hidden;color:var(--ink);font:13px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.app{height:100%;display:flex;flex-direction:column;gap:8px;padding:10px;min-height:0;min-width:0}\n.top{flex:none;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}\n.title{font-weight:700;font-size:15px;white-space:nowrap}\n.steps{display:flex;gap:4px;flex:1 1 auto;justify-content:flex-end;min-width:0}\n.step{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:999px;padding:3px 10px;font:inherit;font-size:12px;cursor:pointer;white-space:nowrap;min-height:26px}\n.step.on{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.body{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain}\n.bar{flex:none;display:flex;align-items:center;gap:8px;justify-content:space-between;min-width:0}\n.hint{color:var(--muted);font-size:12px;min-width:0;flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.btn{flex:none;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:8px;padding:5px 12px;font:inherit;cursor:pointer;min-height:30px;white-space:nowrap}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.chip,.chip{min-height:26px;padding:2px 10px;font-size:12px;border-radius:999px}\n.btn:disabled{opacity:.5;cursor:not-allowed}\n.chip{border:1px solid var(--line);background:transparent;color:var(--ink);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}\n.chip.on{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.stack{display:flex;flex-direction:column;gap:6px;min-width:0}\n.col{display:flex;flex-direction:column;gap:8px;min-width:0}\n.range-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:10px}\n.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(104px,1fr));gap:8px}\n.field{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lbl{font-size:12px;color:var(--muted)}\n.inp{width:100%;min-width:0;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);padding:5px 8px;font:inherit;min-height:30px}\n.ta{resize:vertical;min-height:56px}\n.chips{display:flex;gap:6px;flex-wrap:wrap}\n.row2{display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap}\n.hint2{font-size:11px;color:var(--muted);flex:1 1 120px}\n.msg{font-size:12px;color:var(--muted)}\n.msg.err,.msg.warn{color:var(--ink);font-weight:600}\n.note{border:1px dashed var(--line);border-radius:10px;padding:6px 8px;font-size:12px;background:var(--panel-paper)}\n.note.err{border-style:solid;border-color:var(--accent)}\n.note .long{margin-top:4px;color:var(--muted)}\n.tools{padding:0 2px}\n.allchk,.ack{display:flex;align-items:center;gap:6px;font-size:12px}\n.ack{padding:6px 2px}\n.card input[type=checkbox]{width:18px;height:18px;accent-color:var(--accent);margin:0}\n.row{display:flex;align-items:center;gap:6px;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.row.on{border-color:var(--accent);background:var(--soft)}\n.chk{flex:none;display:grid;place-items:center;width:26px;height:26px;cursor:pointer}\n.rowmain{display:block;flex:1 1 auto;min-width:0;text-align:left;border:0;background:transparent;color:inherit;font:inherit;padding:0;cursor:pointer}\n.rowmain.static{cursor:default}\n.rowtxt{display:flex;flex-direction:column;min-width:0}\n.subj{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.meta{color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.meta.wrap{white-space:normal}\n.reason{font-size:11px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.badge{flex:none;font-size:11px;padding:1px 7px;border-radius:999px;border:1px solid var(--line);color:var(--muted);white-space:nowrap}\n.badge.archive{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.badge.keep{background:var(--soft);color:var(--ink)}\n.empty{padding:12px 4px;display:flex;flex-direction:column;gap:6px;align-items:flex-start}\n.et{font-weight:700}\n.ed{color:var(--muted);font-size:12px}\n.summary{font-weight:700}\n.dsub{font-weight:700;font-size:14px;overflow-wrap:anywhere}\n.snip{font-size:12px;color:var(--muted);overflow-wrap:anywhere}\n.seg{display:flex;gap:4px}\n.segbtn{flex:1;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);border-radius:8px;padding:5px 4px;font:inherit;font-size:12px;cursor:pointer;min-height:30px}\n.segbtn.on{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n\n.card[data-size=\"3x3\"] .app{padding:6px;gap:5px}\n.card[data-size=\"3x3\"] .title,.card[data-size=\"3x3\"] .hint,.card[data-size=\"3x3\"] .meta,.card[data-size=\"3x3\"] .reason,.card[data-size=\"3x3\"] .note .long{display:none}\n.card[data-size=\"3x3\"] .note.open .long{display:block}\n.card[data-size=\"3x3\"] .steps{justify-content:stretch}\n.card[data-size=\"3x3\"] .step{flex:1;padding:2px 4px;font-size:11px;min-height:24px}\n.card[data-size=\"3x3\"] .bar .btn{flex:1}\n.card[data-size=\"3x3\"] .badge{font-size:10px;padding:1px 5px}\n.card[data-size=\"3x3\"] .row{padding:4px 5px;gap:4px}\n.card[data-size=\"3x6\"] .app{padding:8px}\n.card[data-size=\"3x6\"] .top{flex-direction:column;align-items:stretch;gap:5px}\n.card[data-size=\"3x6\"] .steps{justify-content:stretch}\n.card[data-size=\"3x6\"] .step{flex:1;padding:3px 4px}\n.card[data-size=\"3x6\"] .bar{flex-wrap:wrap}\n.card[data-size=\"3x6\"] .hint{flex:1 0 100%}\n.card[data-size=\"3x6\"] .bar .btn{flex:1}\n.card[data-size=\"3x6\"] .badge{font-size:10px;padding:1px 5px}\n.card[data-size=\"6x3\"] .app{padding:8px;gap:6px}\n.card[data-size=\"6x3\"] .range-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n.card[data-size=\"6x3\"] .rowtxt{flex-direction:row;align-items:baseline;gap:8px}\n.card[data-size=\"6x3\"] .rowtxt .subj{flex:1 1 55%}\n.card[data-size=\"6x3\"] .rowtxt .meta{flex:0 1 40%}\n.card[data-size=\"6x3\"] .reason{display:none}\n.card[data-size=\"6x3\"] .row{padding:4px 8px}\n.card[data-size=\"6x3\"] .note .long{display:none}\n.card[data-size=\"6x3\"] .note.open .long{display:block}\n.card[data-size=\"6x6\"] .app{padding:12px;gap:10px}\n.card[data-size=\"6x6\"] .title{font-size:16px}\n.card[data-size=\"6x6\"] .row{padding:8px 10px}\n";
const SRC='connected.mail.message-list';
const DECS={archive:'建议归档',keep:'建议保留',none:'未标注'};
const BLANK={decision:'none',reason:'',picked:false};
const STEPS=[['range','范围'],['review','建议'],['confirm','归档']];

function norm(s){
  s=s&&typeof s==='object'?s:{};
  const r=s.range&&typeof s.range==='object'?s.range:{};
  return {
    range:{from:typeof r.from==='string'?r.from:'',to:typeof r.to==='string'?r.to:''},
    rules:typeof s.rules==='string'?s.rules:'',
    snapshot:s.snapshot&&Array.isArray(s.snapshot.mails)?s.snapshot:null,
    marks:s.marks&&typeof s.marks==='object'?s.marks:{}
  };
}
function pad(n){return String(n).padStart(2,'0')}
function ymd(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function addDays(str,n){const p=str.split('-').map(Number);return ymd(new Date(p[0],p[1]-1,p[2]+n))}
function fmtTime(ms){const d=new Date(ms);return isNaN(d.getTime())?'':ymd(d)+' '+pad(d.getHours())+':'+pad(d.getMinutes())}
function toYmd(v){
  if(v==null||v==='')return '';
  if(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v))return v;
  let d;
  if(typeof v==='number'||(typeof v==='string'&&/^\d{9,13}$/.test(v))){const n=Number(v);d=new Date(n<1e12?n*1000:n)}
  else if(typeof v==='string')d=new Date(v);
  else return '';
  return isNaN(d.getTime())?'':ymd(d);
}
function str(v){
  if(v==null)return '';
  if(typeof v==='string')return v;
  if(typeof v==='number')return String(v);
  if(Array.isArray(v))return str(v[0]);
  if(typeof v==='object')return str(v.name||v.address||v.email||'');
  return '';
}
function pickList(data){
  if(Array.isArray(data))return data;
  if(data&&typeof data==='object'){
    const keys=['messages','items','list','mails','emails','results','data'];
    for(let i=0;i<keys.length;i++){if(Array.isArray(data[keys[i]]))return data[keys[i]]}
  }
  return [];
}
function normMail(m){
  if(!m||typeof m!=='object')return null;
  const id=str(m.id||m.message_id||m.messageId||m.uid||m.mail_id);
  if(!id)return null;
  const raw=m.date||m.received_at||m.receivedAt||m.internal_date||m.internalDate||m.time||m.sent_at||m.sentAt||m.timestamp;
  return {
    id:id,
    subject:str(m.subject||m.title)||'（无主题）',
    from:str(m.from||m.sender||m.from_name||m.from_address),
    date:toYmd(raw),
    snippet:str(m.snippet||m.summary||m.preview||m.abstract)
  };
}
function errText(e){return typeof e==='string'?e:(e&&e.message)||'未知错误'}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,day,runAsync,fetchSource}=ctx;
  const s=norm(state);
  ui.step=ui.step||'range';
  ui.filter=ui.filter||'all';
  ui.scrolls=ui.scrolls||{};
  const snap=s.snapshot;
  const mails=snap?snap.mails:[];
  const job=ui.jobs&&ui.jobs.mail;
  const loading=!!(job&&job.status==='loading');
  const rangeOk=!!(s.range.from&&s.range.to&&s.range.from<=s.range.to);
  const mk=id=>s.marks[id]||BLANK;
  const pickedMails=mails.filter(m=>mk(m.id).picked);
  const pickSig=pickedMails.map(m=>m.id).join('|');
  const stale=!!snap&&(snap.from!==s.range.from||snap.to!==s.range.to);

  function patchMarks(fn){
    return update(st=>{
      const n=norm(st);
      const marks=Object.assign({},n.marks);
      fn(marks);
      return Object.assign({},st,n,{marks:marks});
    });
  }
  function setPicked(ids,val){
    return patchMarks(m=>{ids.forEach(id=>{m[id]=Object.assign({},BLANK,m[id],{picked:val})})});
  }
  function setRange(patch){
    return update(st=>{const n=norm(st);return Object.assign({},st,n,{range:Object.assign({},n.range,patch)})});
  }
  function quick(n){const t=day();return setRange({from:addDays(t,-(n-1)),to:t})}

  function loadMail(r){
    return runAsync('mail',async()=>{
      const data=await fetchSource(SRC);
      const all=pickList(data).map(normMail);
      const valid=all.filter(Boolean);
      const hit=valid.filter(m=>m.date&&m.date>=r.from&&m.date<=r.to);
      hit.sort((a,b)=>a.date<b.date?1:a.date>b.date?-1:0);
      const undated=valid.filter(m=>!m.date).length;
      const invalid=all.length-valid.length;
      await update(st=>{
        const n=norm(st);
        const keep={};
        hit.forEach(m=>{keep[m.id]=1});
        const marks={};
        Object.keys(n.marks).forEach(k=>{if(keep[k])marks[k]=n.marks[k]});
        return Object.assign({},st,n,{marks:marks,snapshot:{from:r.from,to:r.to,at:Date.now(),total:valid.length,undated:undated,invalid:invalid,mails:hit}});
      });
      return {count:hit.length};
    });
  }
  function load(){
    if(!rangeOk||loading)return;
    const r={from:s.range.from,to:s.range.to};
    Promise.resolve(loadMail(r)).then(ok=>{
      if(ok&&ui.step==='range'&&!ui.edit){ui.step='review';redraw()}
    });
  }
  function go(step){ui.step=step;ui.edit=null;redraw()}
  function openEdit(m){const k=mk(m.id);ui.edit={id:m.id,decision:k.decision,reason:k.reason};redraw()}
  function saveEdit(){
    const e=ui.edit;
    return commit(st=>{
      const n=norm(st);
      const marks=Object.assign({},n.marks);
      marks[e.id]=Object.assign({},BLANK,marks[e.id],{decision:e.decision,reason:e.reason.trim()});
      return Object.assign({},st,n,{marks:marks});
    },Object.assign({},ui,{edit:null}));
  }
  function saveRules(){
    const v=ui.rulesDraft!=null?ui.rulesDraft:s.rules;
    return commit(st=>Object.assign({},st,norm(st),{rules:v.trim()}),Object.assign({},ui,{rulesDraft:null}));
  }

  const btn=(label,onClick,cls,dis)=>el('button',{type:'button',class:'btn '+(cls||''),onclick:onClick,disabled:!!dis},label);
  const badge=d=>el('span',{class:'badge '+d},DECS[d]);
  const empty=(t,d,a)=>el('div',{class:'empty'},...[el('div',{class:'et'},t),el('div',{class:'ed'},d),a].filter(Boolean));
  const field=(label,input)=>el('label',{class:'field'},el('span',{class:'lbl'},label),input);
  const dateInput=(v,cb,label)=>el('input',{type:'date',class:'inp',value:v,'aria-label':label,onchange:e=>cb(e.target.value)});


  function sourceStatus(){
    const rows=[];
    if(loading)rows.push(el('div',{class:'msg'},'正在读取邮件…'));
    else if(job&&job.status==='error')rows.push(el('div',{class:'msg err'},'⚠ 读取失败：'+errText(job.error)+'。邮件源需先在平台为此卡片连接邮箱；已有快照保持不变。'));
    if(snap){
      rows.push(el('div',{class:'msg'},'已读取 '+mails.length+' 封（'+snap.from+' 至 '+snap.to+'），更新于 '+fmtTime(snap.at)+(stale?' · 范围已修改，需重新读取':'')));
      if(snap.undated||snap.invalid)rows.push(el('div',{class:'msg'},'另有 '+(snap.undated+snap.invalid)+' 封因缺少日期或编号未纳入。'));
    }else if(!loading&&!(job&&job.status==='error')){
      rows.push(el('div',{class:'msg'},'尚未读取邮件。点「读取邮件」从已连接的邮箱获取邮件元数据。'));
    }
    return el('div',{class:'stack'},...rows);
  }
  function rulesBox(){
    const v=ui.rulesDraft!=null?ui.rulesDraft:s.rules;
    const ta=el('textarea',{class:'inp ta',rows:3,value:v,'aria-label':'AI 建议规则',placeholder:'例如：促销、订阅通知可归档；客户来信和带附件的保留',oninput:e=>{ui.rulesDraft=e.target.value}});
    return el('div',{class:'col'},
      el('span',{class:'lbl'},'给 AI 的建议规则（可选）'),
      ta,
      el('div',{class:'row2'},el('span',{class:'hint2'},'AI 推理未接入：规则仅保存，暂不执行。'),btn('保存规则',saveRules,'chip')));
  }
  function rangeView(){
    let msg=null;
    if(!s.range.from||!s.range.to)msg=el('div',{class:'msg'},'请选择起止日期。');
    else if(s.range.from>s.range.to)msg=el('div',{class:'msg err'},'⚠ 起始日期晚于结束日期。');
    const left=el('div',{class:'col'},
      el('div',{class:'fields'},
        field('起始日期',dateInput(s.range.from,v=>setRange({from:v}),'起始日期')),
        field('结束日期',dateInput(s.range.to,v=>setRange({to:v}),'结束日期'))),
      el('div',{class:'chips'},btn('近7天',()=>quick(7),'chip'),btn('近30天',()=>quick(30),'chip')),
      msg,
      sourceStatus());
    return el('div',{class:'range-grid'},left,rulesBox());
  }

  function row(m){
    const k=mk(m.id);
    const cb=el('input',{type:'checkbox',checked:!!k.picked,'aria-label':'勾选 '+m.subject,onchange:()=>setPicked([m.id],!k.picked)});
    const meta=[m.from,m.date].filter(Boolean).join(' · ');
    return el('div',{class:'row'+(k.picked?' on':'')},
      el('label',{class:'chk'},cb),
      el('button',{type:'button',class:'rowmain','aria-label':'编辑建议：'+m.subject,onclick:()=>openEdit(m)},
        el('span',{class:'rowtxt'},...[
          el('span',{class:'subj'},m.subject),
          el('span',{class:'meta'},meta),
          k.reason?el('span',{class:'reason'},k.reason):null].filter(Boolean))),
      badge(k.decision));
  }
  function reviewView(){
    if(!snap)return empty('还没有邮件数据','先在「范围」里选择日期并读取邮件。',btn('去选择范围',()=>go('range'),'primary'));
    const cnt={archive:0,keep:0,none:0};
    mails.forEach(m=>{cnt[mk(m.id).decision]++});
    const list=ui.filter==='all'?mails:mails.filter(m=>mk(m.id).decision===ui.filter);
    const allPicked=list.length>0&&list.every(m=>mk(m.id).picked);
    const tabs=[['all','全部',mails.length],['archive','归档',cnt.archive],['keep','保留',cnt.keep],['none','未标注',cnt.none]];
    const note=el('div',{class:'note'+(ui.aiTried?' open':'')},
      el('div',{class:'row2'},el('strong',null,'AI 建议：未接入'),btn('让 AI 列出建议',()=>{ui.aiTried=true;redraw()},'chip')),
      el('div',{class:'long'},ui.aiTried
        ?'已确认：平台没有 AI 推理接口，没有对任何邮件做判断，也没有生成示例建议。请点开邮件手动标注「建议归档/保留」和原因；范围里保存的规则会保留。'
        :'平台暂无 AI 推理接口，不会自动判断。可点开邮件手动标注建议与原因。'));
    const chips=el('div',{class:'chips'},...tabs.map(t=>el('button',{type:'button',class:'chip'+(ui.filter===t[0]?' on':''),'aria-pressed':String(ui.filter===t[0]),onclick:()=>{ui.filter=t[0];redraw()}},t[1]+' '+t[2])));
    const tools=el('div',{class:'row2 tools'},
      el('label',{class:'allchk'},el('input',{type:'checkbox',checked:allPicked,disabled:!list.length,'aria-label':'全选当前列表',onchange:()=>setPicked(list.map(m=>m.id),!allPicked)}),el('span',null,'全选')),
      btn('按建议勾选',()=>patchMarks(m=>{mails.forEach(x=>{m[x.id]=Object.assign({},BLANK,m[x.id],{picked:mk(x.id).decision==='archive'})})}),'chip'));
    const parts=[note];
    if(stale)parts.push(el('div',{class:'msg err'},'⚠ 日期范围已修改，当前列表来自 '+snap.from+' 至 '+snap.to+'。'));
    parts.push(chips,tools);
    if(!mails.length)parts.push(empty('该范围内没有邮件','换一个日期范围再读取。'));
    else if(!list.length)parts.push(el('div',{class:'msg'},'此分类下没有邮件。'));
    else list.forEach(m=>parts.push(row(m)));
    return el('div',{class:'stack'},...parts);
  }


  function editView(){
    const m=mails.find(x=>x.id===ui.edit.id);
    const e=ui.edit;
    return el('div',{class:'stack detail'},...[
      el('div',{class:'dsub'},m.subject),
      el('div',{class:'meta wrap'},'发件人：'+(m.from||'未知')+' · 日期：'+(m.date||'未知')),
      m.snippet?el('div',{class:'snip'},m.snippet):null,
      el('div',{class:'lbl'},'建议'),
      el('div',{class:'seg'},...['archive','keep','none'].map(d=>el('button',{type:'button',class:'segbtn'+(e.decision===d?' on':''),'aria-pressed':String(e.decision===d),onclick:()=>{e.decision=d;redraw()}},DECS[d]))),
      el('div',{class:'lbl'},'原因（可修改）'),
      el('textarea',{class:'inp ta',rows:4,value:e.reason,'aria-label':'建议原因',placeholder:'为什么建议归档或保留',oninput:ev=>{e.reason=ev.target.value}})
    ].filter(Boolean));
  }

  function confirmView(){
    if(!snap||!pickedMails.length)return empty('还没有勾选邮件','在「建议」里勾选要归档的邮件，再回来确认。',btn('去勾选',()=>go('review'),'primary'));
    const n=pickedMails.length;
    const tried=ui.tried===pickSig;
